import os

from taf.internal.scf import SCF
from taf.ul.auto_commissioning import auto_commissioning
from taf.rfrl.procedures.resources.python.logger import log_operation, log_step, log_result, log_input_and_output

from taf.rfrl.procedures.resources.python.SCF import get_file_name
from taf.rfrl.procedures.resources.python.vm import \
    get_path_to_scf_dir, get_path_to_deltas_dir, get_path_to_testlines_dir


class JsonDeltaCommissioning:

    def __init__(self):
        self.deltas_dir = get_path_to_deltas_dir()
        self.autocomm_agent = auto_commissioning()

    def __str__(self):
        return 'JsonDeltaCommissioning instance with deltas directory: {0}'.format(
            self.deltas_dir)

    @log_input_and_output
    def inject_delta_to_commissioning(
            self,
            json_delta,
            output_path,
            file_name=None):
        """
        Injects JSON delta file to base_scf from SCF directory, to create new custom scf under output_path
        directory. There are two possible strategies to run this method:

        1. Provide full path to json delta file and base scf file name - if so, then specific json delta
           will be injected into particular scf file, call example:

           inject_delta_to_commissioning(json_delta=/tmp/my_delta.json,
                                         output_path=/tmp/,
                                         file_name=/tmp/base_scf.xml)

        2. Please don't use strategy 2 if You don't know how to implement it, use strategy 1 instead!
           Provide only the name of json delta file and (optionally) file_name of base scf file that user wants to have
           injection to. Json delta file will be automatically search in dedicated directory of VM in SCF/deltas/,
           also SCF file_name may be provided manually if user does not want to get automatically found commissioning
           file from SCF/ directory. Examples:

           inject_delta_to_commissioning(json_delta=5MHz_5G20B, output_path=/tmp/),
           then '5MHz_5G20B.json' from /SCF/deltas/YOUR_VM_HOSTNAME/ will be injected into automatically found scf
           (for example: SCF_SISOAUTO006_master.xml).

           inject_delta_to_commissioning(json_delta=5MHz_5G20B,
                                         output_path=/tmp/,
                                         file_name=SCF_SISOAUTO006_new.xml)
           then '5MHz_5G20B.json' from /SCF/deltas/YOUR_VM_HOSTNAME/ will be injected into provided
           SCF_SISOAUTO006_new.xml file under SCF/ location.

           Newly created SCF after injection will be named {json_delta}.xml and it can be found under
           `output_path` directory.

        :param json_delta: Delta JSON file name to be injected. As provided in instruction above, might be full path
                           to file or just a name of prepared delta (without extension).
        :type json_delta: str
        :param output_path: Path to newly created custom scf's directory after delta injection e.g. /tmp/
        :type output_path: str
        :param file_name: Direct file_name of base_scf from SCF directory.
        :type file_name: str
        """

        custom_scf_name = self._create_name_for_custom_scf(json_delta)

        if '.json' in json_delta:
            log_operation(
                "Injecting specific json delta to particular commissioning strategy has been chosen.")
            self._inject_specific_delta_to_particular_commissioning(
                json_delta_path=json_delta,
                output_path=output_path,
                file_name_path=file_name,
                custom_scf_name=custom_scf_name)
        else:
            log_operation(
                "Automatically injecting json delta to SCF strategy has been chosen.")
            self._inject_auto_delta_to_commissioning(
                json_delta=json_delta,
                output_path=output_path,
                file_name=file_name,
                custom_scf_name=custom_scf_name)

        return output_path + custom_scf_name

    def _inject_specific_delta_to_particular_commissioning(
            self, json_delta_path, output_path, file_name_path, custom_scf_name):
        """
        Injects provided json delta file to particular commissioning.

        :param json_delta_path: Full path to json delta file.
        :type json_delta_path: str
        :param output_path: Output dir for newly created SCF after injection.
        :type output_path: str
        :param file_name_path: Full path to base commissioning file that delta will be injected to.
        :type file_name_path: str
        :custom_scf_name: newly created custom scf's name after delta injection e.g.
        'json_delta_recommissioning_delta.xml'
        :type custom_scf_name: str
        """
        mapped_scf = SCF(file_name_path)
        log_step(
            "Injecting delta from {0} to {1}".format(
                json_delta_path,
                file_name_path))

        self.autocomm_agent.inject_json_delta(
            scf_object=mapped_scf,
            json_addr=json_delta_path
        )

        log_result("Injection performed successfully!")
        saving_path = os.path.join(output_path, custom_scf_name)
        mapped_scf.save(saving_path)
        log_result("Custom scf has been saved to {0}".format(saving_path))

    def _inject_auto_delta_to_commissioning(
            self,
            json_delta,
            output_path,
            file_name,
            custom_scf_name):
        """
        Automatically finds json delta file with scf file name that might be provided or also found automatically
        and injects json delta file into scf commissioning file.

        :param json_delta: JSON delta file name (without extension1) that user wants to inject into base scf, should
                           be placed under SCF/deltas/YOUR_HOSTNAME/ directory.
        :type json_delta: str
        :param output_path: Output dir for newly created SCF after injection.
        :type output_path: str
        :param file_name: Full name (with extension) of base scf file that user wants to get json delta file
                          injected to.
        :type file_name: str
        :custom_scf_name: newly created custom scf's name after delta injection e.g.
        'json_delta_recommissioning_delta.xml'
        :type custom_scf_name: str
        """
        base_scf = os.path.join(
            get_path_to_scf_dir(),
            get_file_name(file_name))
        log_result("Found base scf: {0}".format(base_scf))

        mapped_scf = SCF(base_scf)

        json_addr = self._get_delta_file_path(json_delta, hostname=None)
        log_result("Found json delta file: {0}".format(json_addr))

        log_step("Injecting delta from {0} to {1}".format(json_addr, base_scf))

        self.autocomm_agent.inject_json_delta(
            scf_object=mapped_scf,
            json_addr=json_addr
        )

        log_result("Injection performed successfully!")

        custom_scf_file_dir = os.path.join(output_path, custom_scf_name)
        mapped_scf.save(custom_scf_file_dir)
        log_result(
            "Custom scf has been saved to {0}".format(custom_scf_file_dir))

    @log_input_and_output
    def generate_json_delta(
            self,
            base_scf,
            custom_scf,
            delta_file,
            hostname=None):
        """
        Generates JSON delta between base and custom scf and saves it in deltas directory.
        If custom directory for provided testline doesn't exist, then it will be created.

        :param base_scf: direct path to base scf file (with extension)
        :type base_scf: str
        :param custom_scf: direct path to custom scf file (with extension)
        :type custom_scf: str
        :param delta_file: name of json delta file to be saved (without extension).
        :type delta_file: str
        :param hostname: Creates directory for json delta files under location with name provided
                         by user. None at default, if left unchanged, then directory will be created
                         automatically based on vm's hostname.
        :type hostname: str/bool
        :return: absolute path to delta JSON file.
        :rtype: str
        """
        json_addr = self._get_delta_file_path(delta_file, hostname)
        log_step(
            "Delta file will be saved under {0} location".format(json_addr))

        self.autocomm_agent.generate_json_delta(
            base_scf_addr=base_scf,
            custom_scf_addr=custom_scf,
            json_addr=json_addr
        )
        log_result("Delta file has been created successfully!")

        return json_addr

    @log_input_and_output
    def _get_delta_file_path(self, delta_file, hostname):
        """
        Gets path to json_delta file under proper hostname directory which will be generated
        dynamically if hostname directory won't exist.

        :param delta_file: name of delta JSON file that user wants to get directory (without extension).
        :type delta_file: str
        :param hostname: VM's hostname, if set to None then it will be automatically created
                         with hostname read from socket.
                         If not None, it will try to create files in provided hostname's deltas dir.
        :type hostname: str/None
        :return: absolute path to delta JSON file.
        :rtype: str
        """

        if hostname:
            hostname_dir = self._setup_hostname_dir(hostname)
            return os.path.join(hostname_dir, delta_file + '.json')

        if not os.path.isdir(self.deltas_dir):
            os.makedirs(self.deltas_dir)
        return os.path.join(self.deltas_dir, delta_file + '.json')

    @log_input_and_output
    def _setup_hostname_dir(self, hostname):
        """
        Creates and returns path to hostname directory of testline that JsonDeltaCommissioning is running on.
        If hostname directory doesn't exist (for example You create your json delta file
        for the first time) then directory will be created automatically.
        :param hostname: VM's hostname
        :type hostname: str
        :returns hostname directory
        :rtype: str
        """
        hostname_delta_dir = os.path.join(
            get_path_to_testlines_dir(), hostname, "deltas")
        if not os.path.isdir(hostname_delta_dir):
            os.makedirs(hostname_delta_dir)
            log_step(
                "Couldn't find hostname directory ({0}), so it has been created".format(hostname))
        return hostname_delta_dir

    @staticmethod
    def _create_name_for_custom_scf(json_delta_file):
        """  Creates special name for scf after delta injection in it
        for better, more self-describing scf name.
        :param json_delta_file: (str) Full path or just file json delta file name which was injected in this case.
        :rtype : str
        """
        delta_file_name = json_delta_file.split('/')[-1].split(".")[0]
        return delta_file_name + ".xml"

    def get_valid_scf_file_path(self, json_delta_file):
        """
        Returns valid absolute path to scf that was created via delta injection
        :param json_delta_file: Full path or just file json delta file name
        :type json_delta_file: str
        :return: Full path to previously created scf file
        :rtype: str
        """

        if json_delta_file.endswith(".json"):
            return "/tmp/" + self._create_name_for_custom_scf(json_delta_file)

        return "/tmp/{}.xml".format(json_delta_file)
